// function sanitizeInput(input)
// Agar string nahi: ""
// Trim karo
// Empty hai to: ""
// Warna lowercase return karo

solution:
function sanitizeInput(input) {
  if (typeof input !== "string") return ""
  const trimmed = input.trim()
  if (trimmed.length === 0) return ""
  return trimmed.toLowerCase()
}
